import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Tamralipta Ancient Port Explorer Tests",()=>{it("HTML contains background, location, timeline, trade significance, and religious importance",()=>{const e=readFileSync(resolve(__dirname,"../../tamralipta-port-explorer/index.html"),"utf-8");expect(e).toContain('id="background"'),expect(e).toContain('id="location-timeline"'),expect(e).toContain('id="trade-significance"'),expect(e).toContain('id="culture-religion"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Tamralipta"),expect(e).toContain("Faxian"),expect(e).toContain("Xuanzang")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../tamralipta-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-emerald"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes cleanly",()=>{const e=readFileSync(resolve(__dirname,"../../tamralipta-port-explorer/script.js"),"utf-8");expect(e).toContain("TamraliptaPortExplorer"),expect(e).toContain("setupGalleryModal")})});